import heapq


class OrderBook:
    def __init__(self):
        self.bids = []    # (-price, time, order_id)
        self.asks = []    # (price, time, order_id)
        self.live = {}    # order_id -> [side, price, qty, time]
        self.time = 0

    def add(self, order_id, side, price, qty):
        self.time += 1
        self.live[order_id] = [side, price, qty, self.time]
        if side == "buy":
            heapq.heappush(self.bids, (-price, self.time, order_id))
        else:
            heapq.heappush(self.asks, (price, self.time, order_id))

    def cancel(self, order_id):
        self.live.pop(order_id, None)

    def _top(self, heap):
        # lazy deletion: drop entries whose order is cancelled or filled
        while heap and heap[0][2] not in self.live:
            heapq.heappop(heap)
        return heap[0] if heap else None

    def best_bid(self):
        top = self._top(self.bids)
        return None if top is None else -top[0]

    def best_ask(self):
        top = self._top(self.asks)
        return None if top is None else top[0]

    def match(self):
        fills = []
        while True:
            b, a = self._top(self.bids), self._top(self.asks)
            if b is None or a is None or -b[0] < a[0]:
                return fills
            buy, sell = self.live[b[2]], self.live[a[2]]
            price = buy[1] if buy[3] < sell[3] else sell[1]
            qty = min(buy[2], sell[2])
            fills.append((b[2], a[2], price, qty))
            buy[2] -= qty
            sell[2] -= qty
            if buy[2] == 0:
                del self.live[b[2]]
            if sell[2] == 0:
                del self.live[a[2]]

widget.prelude:
def play(events):
    """Run events on a new OrderBook. Return what each best_bid, best_ask and match call returned."""
    book = OrderBook()
    out = []
    for name, *args in events:
        result = getattr(book, name)(*args)
        if name in ("best_bid", "best_ask", "match"):
            out.append(result)
    return out
